
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_rpp09_N_2_vrho():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_rpp09", 2)
    if not feval._have_vxc:
        pytest.skip("build lacks the derivative order for vrho")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=feval._have_vxc, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["vrho"])
    tgt = out["vrho"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.656709207538965e+00, -6.830471833602652e+00, -6.629174583263569e+00, -6.804798175331394e+00, -6.579923213552342e+00, -6.758263907211533e+00, -6.491883913314960e+00, -6.674231189898446e+00, -6.336566989819776e+00, -6.524951182448220e+00, -6.069752933814943e+00, -6.267685724964855e+00, -5.629968746642660e+00, -5.844355382417509e+00, -4.951169566212645e+00, -5.196011330769249e+00, -4.003519658511017e+00, -4.305563201311825e+00, -2.811716031923161e+00, -3.216212273861101e+00, -1.515294781696001e+00, -1.926455118541897e+00, -8.453535098025359e-01, -6.448365836446212e-01, -9.192723378990805e-01, -5.349802917603995e-01, -8.733388987139170e-01, -6.905297019336052e-01, -6.830720757814053e-01, -6.260052596648082e-01, -4.578469980366243e-01, -4.568740487726866e-01, -2.825979855853642e-01, -3.137176311406996e-01, -1.739792133610850e-01, -2.136869862484500e-01, -1.115631179829129e-01, -1.454847184511527e-01, -7.402717349175388e-02, -9.768057636530705e-02]))
